import os


def load_tax_rate():
    with open(os.path.join(os.path.dirname(__file__), ".env")) as f:
        for line in f:
            k, _, v = line.strip().partition("=")
            if k == "TAX_RATE":
                return float(v)
    raise RuntimeError("TAX_RATE missing")


def subtotal(items):
    return sum(qty * cents for _, qty, cents in items)


def total(items):
    sub = subtotal(items)
    return sub + int(sub * load_tax_rate())

from checkout import subtotal, total


def test_subtotal():
    assert subtotal([("apple", 2, 150), ("bread", 1, 400)]) == 700


def test_total_applies_gst():
    assert total([("apple", 2, 150), ("bread", 1, 400)]) == 770


def test_total_rounds_down():
    assert total([("gum", 1, 5)]) == 5

